<script>
function openEventModal(){document.getElementById('eventForm').reset();document.getElementById('event_id').value='';document.getElementById('eventModalTitle').textContent='Nuevo evento';document.getElementById('eventForm').action='/yaconecta/public/admin/agenda/store';document.getElementById('eventModal').classList.add('open')}function closeEventModal(){document.getElementById('eventModal').classList.remove('open')}function editEvent(event){openEventModal();document.getElementById('eventModalTitle').textContent='Editar evento';document.getElementById('eventForm').action='/yaconecta/public/admin/agenda/update';document.getElementById('event_id').value=event.id;document.getElementById('event_title').value=event.titulo||'';document.getElementById('event_description').value=event.descripcion||'';document.getElementById('event_type').value=event.tipo||'evento';document.getElementById('event_location').value=event.lugar||'';document.getElementById('event_date').value=event.fecha_evento||'';document.getElementById('event_time').value=event.hora_evento||''}function duplicateEvent(event){openEventModal();document.getElementById('event_title').value=(event.titulo||'Evento')+' (copia)';document.getElementById('event_description').value=event.descripcion||'';document.getElementById('event_type').value=event.tipo||'evento';document.getElementById('event_location').value=event.lugar||'';document.getElementById('event_date').value=event.fecha_evento||'';document.getElementById('event_time').value=event.hora_evento||''}
</script>
